import csv
import sys
from statistics import mean, median

def is_float(value):
    try:
        float(value)
        return True
    except ValueError:
        return False

def main(filename):
    with open(filename, newline='') as csvfile:
        reader = csv.DictReader(csvfile)
        data = list(reader)

    if not data:
        print("No data found.")
        return

    # Identify numeric columns
    numeric_cols = []
    for col in data[0].keys():
        # Check if at least one value is numeric in this column
        if any(is_float(row[col]) for row in data):
            numeric_cols.append(col)

    if not numeric_cols:
        print("No numeric columns found.")
        return

    # Collect numeric data for each column
    numeric_data = {col: [] for col in numeric_cols}
    for row in data:
        for col in numeric_cols:
            val = row[col]
            if is_float(val):
                numeric_data[col].append(float(val))

    # Calculate and print mean and median
    for col in numeric_cols:
        col_values = numeric_data[col]
        if col_values:
            print(f"{col}: mean = {mean(col_values):.2f}, median = {median(col_values):.2f}")
        else:
            print(f"{col}: No valid numeric data")

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print("Usage: python csvstats.py filename.csv")
        sys.exit(1)
    main(sys.argv[1])
